#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <sys/swap.h>

// Note: This example uses a placeholder path. 
// To run successfully, the program must be root, 
// and /path/to/swapfile must be a prepared swap area (via mkswap).
#define SWAP_DEVICE_PATH "/path/to/my_swapfile"

void report_error(const char *syscall_name, int err_code) {
    fprintf(stderr, "Error: %s failed on %s: %s (errno %d)\n", 
            syscall_name, SWAP_DEVICE_PATH, strerror(err_code), err_code);
}

int main() {
    // 1. Attempt to activate a swap area (swapon)
    printf("Attempting to activate swap area: %s\n", SWAP_DEVICE_PATH);
    int flags = 0; // Use default settings

    if (swapon(SWAP_DEVICE_PATH, flags) == -1) {
        if (errno == EPERM) {
            fprintf(stderr, "[!] swapon: Permission denied. Must be run as root.\n");
        } else {
            report_error("swapon", errno);
        }
        // Continue to swapoff structure for demonstration
    } else {
        printf("Swap area activated successfully (assuming root access).\n");
    }

    // 2. Attempt to deactivate the swap area (swapoff)
    printf("Attempting to deactivate swap area: %s\n", SWAP_DEVICE_PATH);

    if (swapoff(SWAP_DEVICE_PATH) == -1) {
        if (errno == EPERM) {
            fprintf(stderr, "[!] swapoff: Permission denied. Must be run as root.\n");
        } else {
            // Expected if swapon failed, or path was never active
            report_error("swapoff", errno);
        }
        return EXIT_FAILURE;
    }

    printf("Swap area deactivated successfully.\n");
    return EXIT_SUCCESS;
}
